#!/usr/bin/env python3
from pathlib import Path
import base64, py_compile

ROOT=Path.cwd()
SERVER=ROOT/'extensions'/'eira_inventor_holographic_lab'/'server.py'
if not SERVER.is_file(): raise SystemExit('FAIL: server.py not found')
s=SERVER.read_text(encoding='utf-8')

if "/api/archive-upload" not in s:
    raise SystemExit('FAIL: archive upload endpoint missing from server.py')
if "/api/archive" not in s:
    raise SystemExit('FAIL: archive search endpoint missing from server.py')

B64=''' '''
# Correct a single accidental space in the encoded payload if present from transport formatting.
B64=B64.replace(' ','')
extra=base64.b64decode(B64).decode('utf-8')
marker='<script id="eira-archive-controls-final">'
if marker in s:
    start=s.index(marker)
    end=s.index('</script>',start)+len('</script>')
    s=s[:start]+s[end:]
# Important: append as a separate script AFTER the existing script closes.
needle='</main></body></html>'
if needle not in s:
    raise SystemExit('FAIL: html closing marker not found')
s=s.replace(needle,'</main>'+extra+'</body></html>',1)
SERVER.write_text(s,encoding='utf-8')
py_compile.compile(str(SERVER),doraise=True)
print('ARCHIVE_CONTROLS_SEPARATE_SCRIPT_PASS')
print('server.py syntax: PASS')
print('separate Safari script: PASS')
